namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public interface INotificationService
{
    Task<List<Notification>> GetNotificationsAsync();
    Task<List<Notification>> GetNewNotificationsSinceAsync(DateTime since);
}

public class NotificationService : INotificationService
{
    private static int _nextId = 100;
    private static readonly List<Notification> _seedData = new()
    {
        new(1, "Welcome to the app!", DateTime.UtcNow.AddHours(-2)),
        new(2, "Your profile was updated.", DateTime.UtcNow.AddHours(-1)),
        new(3, "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-30)),
    };

    public Task<List<Notification>> GetNotificationsAsync()
    {
        return Task.FromResult(_seedData.ToList());
    }

    public Task<List<Notification>> GetNewNotificationsSinceAsync(DateTime since)
    {
        // Simulate a new notification arriving roughly every 10 seconds
        var now = DateTime.UtcNow;
        if (now.Second % 10 < 5 && Random.Shared.Next(3) == 0)
        {
            var id = Interlocked.Increment(ref _nextId);
            var n = new Notification(id, $"New alert #{id} at {now:T}", now);
            _seedData.Add(n);
        }

        var results = _seedData.Where(n => n.Timestamp > since).ToList();
        return Task.FromResult(results);
    }
}

