    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                var newOnes = await NotificationService.GetNewNotificationsSinceAsync(_lastCheck);
                if (newOnes.Count > 0)
                {
                    foreach (var n in newOnes)
