+    }
+</h1>
+
+@if (notifications is null)
+{
+    <p><em>Loading...</em></p>
+}
+else if (notifications.Count == 0)
+{
+    <p>No notifications.</p>
+}
+else
+{
+    <ul class="list-group">
+        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
+        {
+            <li class="list-group-item d-flex justify-content-between align-items-center">
+                @n.Message
+                <small class="text-muted">@n.Timestamp.ToString("g")</small>
+            </li>
+        }
+    </ul>
+}
+
+@code {
+    private List<Notification>? notifications;
+    private CancellationTokenSource? _cts;
+    private DateTime _lastCheck;
+
+    [PersistentState]
+    public List<Notification>? PersistedNotifications { get; set; }
+
+    protected override async Task OnInitializedAsync()
+    {
+        // Restore from prerender state if available; otherwise fetch once.
+        if (PersistedNotifications is not null)
+        {
+            notifications = PersistedNotifications;
+        }
+        else
+        {
+            notifications = await NotificationService.GetNotificationsAsync();
+            PersistedNotifications = notifications;
+        }
+
+        _lastCheck = notifications.Count > 0
+            ? notifications.Max(n => n.Timestamp)
+            : DateTime.UtcNow;
+    }
+
+    protected override void OnAfterRender(bool firstRender)
+    {
+        // OnAfterRender never fires during prerender — safe to start polling here.
+        if (firstRender)
+        {
+            _cts = new CancellationTokenSource();
+            _ = PollForNotificationsAsync(_cts.Token);
+        }
+    }
+
+    private async Task PollForNotificationsAsync(CancellationToken ct)
+    {
+        while (!ct.IsCancellationRequested)
+        {
+            try
+            {
+                await Task.Delay(TimeSpan.FromSeconds(5), ct);
+
+                var newOnes = await NotificationService.GetNewNotificationsSinceAsync(_lastCheck);
+                if (newOnes.Count > 0)
+                {
+                    foreach (var n in newOnes)
+                    {
+                        if (notifications!.All(x => x.Id != n.Id))
+                        {
+                            notifications.Add(n);
+                        }
+                    }
+
+                    _lastCheck = notifications.Max(n => n.Timestamp);
+                    await InvokeAsync(StateHasChanged);
+                }
+            }
+            catch (TaskCanceledException)
+            {
+                break;
+            }
+        }
+    }
+
+    public async ValueTask DisposeAsync()
+    {
+        if (_cts is not null)
+        {
+            await _cts.CancelAsync();
+            _cts.Dispose();
+        }
+    }
+}
